// Level "Canvas": 8 × 8 cells of 10 mm inside the frame.
// Pen down when Me and It are in the same cell; it stays down until they are more
// than 1.5 cells apart, so a small drift of one hand does not break the line.

const N = 8, CELL = 10, X0 = 140, Y0 = 63;
const PEN_UP_DISTANCE = 1.5 * CELL;
const COLORS = {
  red:   { fill: "#e63946", tone: 330 },
  green: { fill: "#2a9d4b", tone: 523 },
  blue:  { fill: "#2f6fdf", tone: 784 },
};

const pixels = new Array(N * N).fill(null); // colour name per cell, null = empty
const marks = new Array(N * N).fill(null);  // the coloured square in the preview
let color = "red";
let erasing = false;
let penDown = false;

/** Cell index under a point, or -1 outside the canvas. */
function cellAt(p) {
  const col = Math.floor((p.x - X0) / CELL), row = Math.floor((p.y - Y0) / CELL);
  return col >= 0 && col < N && row >= 0 && row < N ? row * N + col : -1;
}

function setPixel(i, value) {
  if (i < 0 || pixels[i] === value) return;
  pixels[i] = value;
  marks[i]?.remove();
  marks[i] = null;
  if (value) {
    const x = X0 + ((i % N) + 0.5) * CELL, y = Y0 + (Math.floor(i / N) + 0.5) * CELL;
    marks[i] = panto.entity({ x, y, r: CELL / 2, color: COLORS[value].fill });
    sound.beep(COLORS[value].tone, 70, { volume: 0.15 });
  } else {
    sound.tick();
  }
}

async function chirp(from, to) {
  await sound.beep(from, 50, { volume: 0.15 });
  sound.beep(to, 70, { volume: 0.15 });
}

function updatePen() {
  const meCell = cellAt(me.position);
  if (!penDown && meCell >= 0 && meCell === cellAt(it.position)) {
    penDown = true;
    chirp(500, 800);
  } else if (penDown && (meCell < 0 || distance(me, it) > PEN_UP_DISTANCE)) {
    penDown = false;
    chirp(800, 500);
  }
  if (penDown) setPixel(meCell, erasing ? null : color);
}

// It reads: every new cell says its colour, a tick means empty
let itCell = -1;
it.onMove((p) => {
  updatePen();
  const i = cellAt(p);
  if (i === itCell) return;
  itCell = i;
  if (i < 0 || penDown) return;
  if (pixels[i]) speak(pixels[i], { interrupt: true });
  else sound.tick();
});

// Me draws: a quiet low click at each cell border while the pen is up
let meCell = -1;
me.onMove((p) => {
  updatePen();
  const i = cellAt(p);
  if (i === meCell) return;
  meCell = i;
  if (i >= 0 && !penDown) sound.beep(180, 20, { volume: 0.08 });
});

// --- voice commands --------------------------------------------------------

// speech recognition often hears "red" as "read"
const MISHEARD = { red: ["read"], green: [], blue: [] };

for (const name of Object.keys(COLORS)) {
  voice.intent(name, {
    examples: [name, ...MISHEARD[name], `paint ${name}`, `use ${name}`, `switch to ${name}`, `make it ${name}`],
    interim: false,
    onMatch: () => {
      color = name;
      erasing = false;
      speak(name, { interrupt: true });
    },
  });
}

voice.intent("erase", {
  examples: ["erase", "remove", "eraser", "delete colour", "rubber"],
  interim: false,
  onMatch: () => {
    erasing = true;
    speak("Erase", { interrupt: true });
  },
});

voice.intent("status", {
  examples: ["which colour", "what colour is it", "which mode", "what am I painting"],
  interim: false,
  onMatch: () => speak(erasing ? "Erasing" : `Painting ${color}`, { interrupt: true }),
});

// Level "Trace": the canvas of level 1, plus It can show you what you painted.
// Say "show red" (or green, blue): It moves through every red cell, a tone at each,
