// --- It traces a colour ----------------------------------------------------

const centerOf = (i) => ({ x: X0 + ((i % N) + 0.5) * CELL, y: Y0 + (Math.floor(i / N) + 0.5) * CELL });

/** The cells of a colour in tour order: always the nearest cell next. */
function tour(name) {
  const left = pixels.map((v, i) => (v === name ? i : -1)).filter((i) => i >= 0);
  const order = [];
  let from = it.position;
  while (left.length) {
    let best = 0;
    left.forEach((i, k) => { if (distance(from, centerOf(i)) < distance(from, centerOf(left[best]))) best = k; });
    const [i] = left.splice(best, 1);
    order.push(i);
    from = centerOf(i);
  }
  return order;
}

let stopTour = false;

async function show(name) {
  if (tracing) return;
  const cells = tour(name);
  if (!cells.length) return speak(`Nothing is ${name}.`, { interrupt: true });
  tracing = true;
  stopTour = false;
  penDown = false;
  await speak(`${cells.length} ${name}`, { interrupt: true });
  for (const i of cells) {
    if (stopTour) break;
    await it.moveTo(centerOf(i), { hold: true });
    sound.beep(COLORS[name].tone, 120, { volume: 0.15 });
    await wait(250);
  }
  it.free();
  tracing = false;
  sound.beep(500, 70, { volume: 0.15 });
}

for (const name of Object.keys(COLORS)) {
  voice.intent(`show_${name}`, {
    examples: [`show ${name}`, `show me ${name}`, `where is ${name}`, `trace ${name}`],
    interim: false,
    onMatch: () => show(name),
  });
}

voice.intent("stop", {
  examples: ["stop", "enough", "cancel"],
  interim: false,
  onMatch: () => { stopTour = true; },
});

